import json,csv,html
from pathlib import Path
D=Path(__file__).parent;s=json.loads((D/'summary.json').read_text('utf8'));a=s['strict_articles'];b=s['strict_mainland_articles']
report=['# DeepSeek 10月上半月：剔除国外网站后的文章字数分析','', '**结论：字数与重复引用的关系较弱，没有证据表明单独把文章加长就能显著提高推荐概率。**','', '## 数据范围与清洗','',f"- 时间：2026-10-01—10-15；数据快照 {s['window']['as_of']}。",'- 读取主 GEO PostgreSQL 中成功记录及 production_valid=true 的来源；不是内容创作专用补采。只读现有记录与正文缓存，未调用付费模型或重新抓取。',f"- 成功采集 {s['captures']} 次，来源列表完整 {s['complete_captures']} 次；覆盖 {s['questions']} 个问题、14个实际采集日期。10月5日无成功记录，不能视为该日零推荐。",'- 全部记录去重后 3,455 个 URL：大陆区域站点 1,604，港澳台区域站点 493，已识别国外站点 1,316，归属未确认 38，畸形地址 4。', '- 已识别国外网站全部排除；归属未确认及畸形地址保守单列，不混入国内主分析。港澳台不作为国外，保留地域标记，并另给仅大陆结果。','- 地域按出版/运营区域与站点版本判断，不按服务器 IP 或品牌国籍判断。已知大陆内容平台及大陆区域域名归入大陆；已知国外出版平台和国家地区站点剔除。通用域名不能仅凭.com判断；完整规则和逐域名归类见域名地域核对表。小型站点仍可能误分类，需进一步逐站核实。','- 非国外且来源完整的链接中，明显商品/电商页面356、百科/搜索47、专利/目录11、问答正文119单列；文章候选1,564个。按URL/域名和路径规则分类，非逐篇人工鉴定，仍可能残留其他页面类型。',f"- 文章候选再排除正文缺失、失败、低质量及有效字符不足80的页面，得到 {a['valid_articles']:,} 个有效文章URL（文章候选的 {a['coverage']:.1%}）；其中大陆 {b['valid_articles']:,}、港澳台 {a['valid_articles']-b['valid_articles']:,}。",'- 字数为提取正文中的汉字、英文字母、数字字符数，不计空白、标点；明细另有纯汉字数及非空白字符数。使用现存正文快照，正文抓取时间可能晚于推荐时间；抽取结果可能残留标题/作者/导航，并非人工精确字数。','', '## 文章长度分布','', '| 指标 | 非国外文章（含港澳台） | 仅大陆文章 |','|---|---:|---:|',f"| 可分析文章 | {a['valid_articles']:,} | {b['valid_articles']:,} |",f"| 字数中位数 | {a['median']:,.0f} | {b['median']:,.0f} |",f"| 中间50%字数范围 | {a['p25']:,.0f}—{a['p75']:,.0f} | {b['p25']:,.0f}—{b['p75']:,.0f} |",'', '| 字数区间 | 文章数 | 文章占比 | 每篇平均被引用次数 |','|---|---:|---:|---:|']
for x in a['bins']:report.append(f"| {x['bin']} | {x['unique_articles']} | {x['article_share']:.1%} | {x['mean_recommendations']:.2f} |")
report += ['', '非国外文章的1,000—2,999字合计约49%；3,000—4,999字约19%。这只是已被引用文章的长度分布，不能视作各长度档的总体推荐概率。','', '## 字数与引用次数的关系','', '| 比较口径 | 非国外文章（含港澳台） | 仅大陆文章 |','|---|---:|---:|',f"| Spearman秩相关：字数 vs 引用次数 | {a['association']['spearman']:.3f} | {b['association']['spearman']:.3f} |",f"| 同网站同问题组内：对数字数 vs log(1+引用次数)相关 | {a['adjusted']['within_domain_question_log_correlation']:.3f} | {b['adjusted']['within_domain_question_log_correlation']:.3f} |",'', '- 含港澳台的总体相关约0.118，属于较弱关联；仅大陆约0.053，更接近零。','- 限定同网站、同问题组内后，相关分别降至约0.043和0.028，未观察到稳定的组内正相关。',f"- 分组比较只使用每组至少5篇、字数和引用次数均有变化的组：非国外文章 {a['adjusted']['n']} 篇/{a['adjusted']['groups']}组；大陆文章 {b['adjusted']['n']}篇/{b['adjusted']['groups']}组。只能减少网站和问题这两种混杂，不能视为因果校正。",'- 5,000字以上组在混合样本中平均引用较多，但地域、站点、主题和内容覆盖也不同，不能归因为“多写字”。','- 初次入样时间和监测频次也会改变累计引用数；文章年龄、收录、排名等未全面控制。','', '## 对内容创作的含义','', '目前适合把约2,000—3,500字作为后续对照实验的一档，而不是给全部文章设置越长越好的规则。这只是根据本样本常见长度提出的测试范围，不是经过验证的最优长度。不要仅凭这里的长文组均值就统一扩写到5,000或8,000字。','', '若要测真正的入选概率，需要加入所有已发布文章，包括零引用文章，并在同问题、网站、相近发布时间和固定观察天数下随机比较不同字数档。只看已经入选的链接，无法计算总体入选概率。本文“引用”指答复来源列表出现，不等于品牌被推荐。','', '## 局限与复核','', '- 来源缺失、正文访问限制、抽取质量和地域判定会造成选择偏差。','- 问答、商品页、百科已经尽量分离，规则不等同人工逐页审阅。','- 同一URL每次答复最多算一次，独立答复中重复出现保留。同内容转载可能以多个URL出现；另外的同正文哈希合并敏感性结果见summary.json（含问答口径）。','- 探索性相关统计并未消除所有混杂。重复引用和转载使样本不完全独立，置换检验和文章级近似自助区间不构成严格的随机实验结论。','', '域名核对参考官方页面：',[ ]]
# Remove temporary placeholder and append primary verification sources.
report=[x for x in report if isinstance(x,str)]
report += ['','- [时尚COSMO：关于我们](https://cosmopolitancn.com/cosmo/about)（大陆出版主体，避免把国际品牌中国站误归国外）','- [中国食品药品国际交流中心](https://www.ccfdie.org/cn/index.htm)','- [扬子晚报技术服务及版权页](https://www.yzwb.net/zt/yzservice/index.html)','','文件：DeepSeek文章样本明细.csv、DeepSeek全部信源字数及地域.csv、域名地域核对表.csv、summary.json。']
(D/'DeepSeek上半月分析报告.md').write_text('\n'.join(report)+'\n',encoding='utf8')
with (D/'DeepSeek字数区间汇总.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['scope',*a['bins'][0]]);w.writeheader()
 for label,v in [('非国外文章_含港澳台',a),('仅大陆文章',b)]:
  for x in v['bins']:w.writerow(dict(scope=label,**x))
svg=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 520"><rect width="1100" height="520" fill="#f7fafc"/><g font-family="Microsoft YaHei,sans-serif" fill="#213c4a">','<text x="40" y="42" font-size="26" font-weight="700">DeepSeek：剔除国外站点后的文章字数</text>','<text x="40" y="72" font-size="14">2026年10月1—15日 · 1,018篇有效文章 · 图中比例为文章分布，并非推荐概率</text>']
for i,x in enumerate(a['bins']):
 y=111+i*53;w=x['article_share']*2000
 svg.append(f'<text x="40" y="{y+21}" font-size="16">{x["bin"]}</text><rect x="190" y="{y}" width="{w:.1f}" height="30" fill="#177e86" rx="4"/><text x="{205+w:.1f}" y="{y+21}" font-size="15">{x["unique_articles"]}篇 · {x["article_share"]:.1%}</text>')
svg+=['<text x="40" y="466" font-size="16">字数中位数：2,513；仅大陆样本：852篇，中位数2,396</text>','<text x="40" y="496" font-size="13" fill="#607482">正文汉字、字母和数字字符；已剔除明显商品页、百科、问答等，以及低质量/缺失正文。</text></g></svg>']
(D/'DeepSeek字数分布.svg').write_text(''.join(svg),encoding='utf8')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>DeepSeek 上半月字数分析</title><style>body{font:16px/1.75 "Microsoft YaHei",sans-serif;color:#203745;background:#f4f7fa;margin:0}main{max-width:1040px;margin:auto;padding:28px}section{background:#fff;padding:24px;border:1px solid #dce5ea;border-radius:14px;margin:20px 0}h1{font-size:29px}h2{font-size:20px}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border-bottom:1px solid #e2e8ec;text-align:left}select{font:inherit;padding:7px}.key{color:#087d7e;font-size:21px}.muted{color:#617684}@media(max-width:650px){main{padding:12px}section{padding:15px}}</style><main><h1>DeepSeek：文章越长，越容易被推荐吗？</h1><p class="muted">2026年10月1—15日 · 已剔除国外站点 · 14个日期有成功记录，缺10月5日</p><section><p class="key">现有数据未证明单独加长文章会提高推荐概率。</p><p>剔除明显商品页、百科、问答及低质量正文后，得到1,018篇文章。含港澳台样本关联较弱，仅大陆样本接近零；同网站同问题内比较后更弱。</p></section><section>'''+''.join(svg)+'''</section><section><label>统计范围：<select id="scope"><option value="strict_articles">非国外文章（含港澳台）</option><option value="strict_mainland_articles">仅大陆文章</option><option value="primary">非国外文章＋问答正文</option></select></label><div id="metrics"></div><table><thead><tr><th>字数区间</th><th>文章数</th><th>文章占比</th><th>每篇平均引用次数</th></tr></thead><tbody id="bins"></tbody></table><p class="muted">次数为该日期范围内累计出现次数；不能当作所有已发布文章的推荐概率。</p></section><section><h2>网站地域与样本清洗</h2><p>原始去重链接3,455个；已识别国外1,316个排除，归属待核实38个、畸形地址4个保守单列。大陆区域站点1,604个、港澳台493个。再剔除明显非文章页面与正文质量不合格样本。</p><p>网站地域按区域版本和可识别的出版平台判断，未把.com直接当成国外。港澳台不计作国外，可切换仅大陆结果。</p><p>现有正文快照仍可能带少量标题或导航，且约三分之一文章候选无合格正文。域名规则并非逐站法律归属鉴定。</p><h2>这对创作意味着什么</h2><p>可以把2,000—3,500字作为后续受控测试的一档。目前没有依据把全部文章统一加长到5,000或8,000字。</p><p>要计算实际推荐概率，需要把零引用的已发布文章也纳入分母，并控制网站、问题、发布时间和观察天数。</p><p>详细方法、逐链接数据和地域核对表见同目录报告及CSV。</p></section></main><script>'''
page+='const data='+json.dumps(s,ensure_ascii=False)+';function render(){const v=data[document.querySelector("#scope").value];document.querySelector("#metrics").innerHTML=`<p><b>${v.valid_articles.toLocaleString()}个有效URL</b> · 中位数 ${Math.round(v.median).toLocaleString()}字<br>字数与引用次数秩相关 ${v.association.spearman.toFixed(3)}；同网站同问题组内相关 ${v.adjusted.within_domain_question_log_correlation.toFixed(3)}</p>`;document.querySelector("#bins").innerHTML=v.bins.map(b=>`<tr><td>${b.bin}</td><td>${b.unique_articles}</td><td>${(b.article_share*100).toFixed(1)}%</td><td>${b.mean_recommendations.toFixed(2)}</td></tr>`).join("")}document.querySelector("#scope").onchange=render;render();</script>'
(D/'DeepSeek上半月分析报告.html').write_text(page,encoding='utf8')
print('DeepSeek report generated')
